CREATE TABLE users (
    id INT NOT NULL,
    name VARCHAR(64),
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

CREATE TABLE orders (
    order_id INT,
    total DECIMAL(10,2),
    PRIMARY KEY (`order_id`)
) ENGINE=MyISAM;

CREATE TABLE tags (
    tag_id INT,
    label TEXT COMMENT 'tag text',
    PRIMARY KEY (`tag_id`)
) ENGINE=InnoDB;

CREATE TABLE logs (
    log_id BIGINT,
    msg TEXT,
    PRIMARY KEY (`log_id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

